<div class="grid gap-4 md:grid-cols-2"><x-form-field label="تاريخ التقرير" name="report_date" type="date" :value="$report->report_date ?? now()->toDateString()" required/><x-form-field label="عدد القضايا التي تمت متابعتها" name="cases_worked" type="number" :value="$report->cases_worked ?? 0" required min="0"/><x-form-field label="عدد المكالمات" name="calls_count" type="number" :value="$report->calls_count ?? 0" required min="0"/><x-form-field label="عدد الزيارات" name="visits_count" type="number" :value="$report->visits_count ?? 0" required min="0"/><x-form-field label="عدد الوعود" name="promises_count" type="number" :value="$report->promises_count ?? 0" required min="0"/><x-form-field label="إجمالي المبالغ الموعودة" name="promised_amount" type="number" :value="$report->promised_amount ?? 0" required min="0" step="0.01"/><x-form-field label="إجمالي التحصيل" name="collected_amount" type="number" :value="$report->collected_amount ?? 0" required min="0" step="0.01"/><div class="md:col-span-2"><x-textarea-field label="ملاحظات" name="notes" :value="$report->notes ?? null"/></div></div>
